records.raw:
SELECT COUNT(*) FROM (
  SELECT customer_id
  FROM orders
  GROUP BY customer_id
  HAVING EXTRACT(YEAR FROM MIN(order_purchase_timestamp)) = 2018
) AS first_orders_2018;

