records.raw:
SELECT AVG(total_revenue) FROM (
  SELECT o.customer_id, SUM(op.payment_value) AS total_revenue
  FROM orders o
  JOIN order_payments op ON o.order_id = op.order_id
  GROUP BY o.customer_id
) t;

