records.raw:
SELECT AVG(EXTRACT(EPOCH FROM (order_delivered_customer_date - order_delivered_carrier_date))/86400.0) AS avg_days
FROM orders
WHERE order_delivered_carrier_date IS NOT NULL AND order_delivered_customer_date IS NOT NULL;

